#!/usr/bin/env node
/**
 * Launch to 150km orbit using ksp-mcp
 */

import { KosConnection } from '../../transport/kos-connection.js';
import { AscentProgram } from '../../mechjeb/programs/ascent.js';

async function main() {
  console.log('=== Launching to 150km Orbit ===\n');

  const conn = new KosConnection({
    cpuLabel: 'guidance',
  });

  try {
    console.log('Connecting to kOS...');
    await conn.connect();
    console.log(`Connected!\n`);

    const ascent = new AscentProgram(conn);

    console.log('Configuring ascent to 150km...');
    const handle = await ascent.launchToOrbit({
      altitude: 150000,  // 150km
      inclination: 0,
      skipCircularization: false,
      autoStage: true,
      autoWarp: true,
    });

    console.log('🚀 Launch initiated!\n');
    console.log('Monitoring ascent...\n');

    // Monitor progress
    for (let i = 0; i < 120; i++) {
      await new Promise(r => setTimeout(r, 5000));

      const progress = await handle.getProgress();

      console.log(
        `[${progress.phase.padEnd(14)}] ` +
        `ALT: ${Math.round(progress.altitude / 1000).toString().padStart(4)}km  ` +
        `APO: ${Math.round(progress.apoapsis / 1000).toString().padStart(4)}km  ` +
        `PER: ${Math.round(progress.periapsis / 1000).toString().padStart(4)}km  ` +
        `MJ: ${progress.enabled ? 'ON' : 'off'}`
      );

      if (progress.phase === 'complete') {
        console.log('\n✅ ORBIT ACHIEVED!');
        console.log(`Final orbit: ${Math.round(progress.apoapsis / 1000)}km x ${Math.round(progress.periapsis / 1000)}km\n`);
        break;
      }

      if (!progress.enabled && progress.periapsis < 70000) {
        console.log('\n⚠️  MechJeb disengaged before orbit.');
        break;
      }
    }

  } catch (error) {
    console.error('Error:', error instanceof Error ? error.message : String(error));
  } finally {
    await conn.disconnect();
    console.log('Disconnected.\n');
  }
}

main().catch(console.error);
